import json
import os
import requests

payload = json.loads(r'''{
  "source": "data:text/plain;base64,SGVsbG8gQ2x1YWl6IQ==",
  "output_controls": {
    "return_text": true
  },
  "chunking_strategy": {
    "type": "semantic",
    "max_chunk_size": 512,
    "overlap": 0
  }
}''')
response = requests.post(
    "http://127.0.0.1:8000/v1/ingest",
    headers={"Authorization": "Bearer " + os.environ["CLUAIZ_TOKEN"]},
    json=payload
)
response.raise_for_status()
data = response.json()
print(data["status"])
for source in data["processed_sources"]:
    print(source["status"], source.get("chunks", []))

